import { tags } from "typia";

/**
 * Temporal search volume analysis showing usage patterns over time.
 *
 * Provides time-series data for search activity patterns, helping identify peak
 * usage periods, seasonal trends, and overall search engagement within the
 * economic discussion platform. This information supports capacity planning and
 * optimization decisions.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISearchVolumeTrend = {
  /** Date for this search volume data point. */
  date: string & tags.Format<"date">;

  /** Total number of search queries executed on this date. */
  total_queries: number & tags.Type<"int32">;

  /** Number of unique search queries executed on this date. */
  unique_queries: number & tags.Type<"int32">;

  /** Number of unique users who performed searches on this date. */
  active_users: number & tags.Type<"int32">;

  /** Hour of day with highest search activity (24-hour format). */
  peak_hour?: string | undefined;
};
